INSERT INTO `categories` VALUES ('import-cat-aerosol-products','Aerosol Products','aerosol-products','',NULL,'/imported-products/air-freshener-oudh.png','blue',1,100,'2026-10-22 12:38:11','2026-10-22 12:38:11'),('import-cat-air-freshener-dispensers','Air Freshener Dispensers','air-freshener-dispensers','','import-cat-dispensers','/imported-products/air-freshener-dispenser-hi-care.jpg','green',0,401,'2026-10-22 12:38:11','2026-10-22 12:38:11'),('import-cat-air-fresheners','Air Fresheners','air-fresheners','','import-cat-aerosol-products','/imported-products/air-freshener-oudh.png','green',0,101,'2026-10-22 12:38:11','2026-10-22 12:38:11'),('import-cat-all-purpose-cleaner','All Purpose Cleaner','all-purpose-cleaner','Hygiene Link is a leading Super care All-purpose cleaner supplier in Muscat, Oman . It is easy to use with our cost-effective formula. It can effectively penetrate tough grease, food, soaps, lime, and other residues. Our all-purpose cleaners have a pleasant scent. These are extremely effective, provide environmentally friendly options, and assist us in streamlining our supply chain. Our all-purpose cleaner has been clinically proven to kill 99.9% of bacteria and germs in just 60 seconds.\n\nFormulated with white vinegar and sugar surfactants, this non-toxic cleaner is very safe to use for your loving four-legged pet. This cleaner is used to remove residues while disinfecting the bathroom surfaces by using Clorox\'s signature ingredient. As a leading Hi care All-purpose cleaner supplier in Muscat, Oman we deliver a powerful plant-based solution that not only can tackle messes but also gentle at the places where you eat or prepare food. It works best with non-porous materials such as acrylic, quartz, brass, stainless steel, glass, and glass tiling. However, as long as you quickly wipe it away you can use it for other matters. It breaks down messes without the preservation of harsh chemicals or synthetic agents on the surface.\n\nAll Purpose Cleaner Manufacturer in Muscat, Oman\n\nYou will be delighted to be always ready to clean the dust, dirt, food, and generic daily grime from your car with our eco-friendly all purpose cleaner. Single-use cleaning wipes are especially helpful if you are cleaning on a spot so that you do not have to put away any cleaning mess before your normal cleaning arsenal is back home.\n\nLemon verbena, lavender, peony, basil, and orange clove are only a few of the signature scents of our herbal, eco-friendly all-purpose cleaner. It is suitable for use on a number of surfaces in the kitchen, dining room, bathroom, living room, and home office.','import-cat-detergent-disinfectants','','green',0,301,'2026-10-22 12:38:11','2026-10-22 12:38:11'),('import-cat-aluminium-handles','Aluminium Handles','aluminium-handles','','import-cat-miscellaneous-products','/imported-products/aluminum-stick-120.jpg','green',0,701,'2026-10-22 12:38:11','2026-10-22 12:38:11'),('import-cat-bleaches','Bleaches','bleaches','','import-cat-detergent-disinfectants','/imported-products/bleach-lemon.png','green',0,302,'2026-10-22 12:38:11','2026-10-22 12:38:11'),('import-cat-branded-cleaning-chemicals','Branded Cleaning Chemicals','branded-cleaning-chemicals','','import-cat-detergent-disinfectants','/imported-products/dac-and-clorox.png','green',0,303,'2026-10-22 12:38:11','2026-10-22 12:38:11'),('import-cat-brooms-and-mops','Brooms and Mops','brooms-and-mops','',NULL,'/imported-products/printed-soft-broom-with-plastic-coated-handle.png','blue',1,200,'2026-10-22 12:38:11','2026-10-22 12:38:11'),('import-cat-car-care-products','Car care products','car-care-products','','import-cat-detergent-disinfectants','/imported-products/battery-water.png','green',0,304,'2026-10-22 12:38:11','2026-10-22 12:38:11'),('import-cat-carpet-floor-care-products','Carpet & Floor Care Products','carpet-floor-care-products','','import-cat-detergent-disinfectants','/imported-products/carpet-shampoo-premium-high-foam.jpg','green',0,305,'2026-10-22 12:38